            }
        }

        // Convert the list back to an array
        int[] resultArray = filteredArray.ToArray();

        // Print the result
        Console.WriteLine("Resulting array:");
        foreach (int item in resultArray)
        {
            Console.Write(item + " ");
        }
    }
}
```

